    while (y>0 && !placed.some(p=>collides({...it,y:y-1}, p))) y--;
    placed.push({...it, y});
  }
  return placed;
}

function resolveCollisions(items, active): LayoutItem[] {
  // push items that collide with active downward, recursively
  let res = items.map(i=>({...i}));
  const act = res.find(i=>i.id===active.id)!;
