```
function moveItem(items, id, x, y, w?, h?) {
  let res = items.map(i => i.id===id ? {...i, x, y, w:w??i.w, h:h??i.h} : {...i});
  // resolve collisions iteratively: for any pair colliding where one is the moved item or pushed items, push down
  for (let iter=0; iter<100; iter++) {
    let any = false;
    const sorted = [...res].sort((a,b)=> a.y-b.y || a.x-b.x);
    for (let i=0;i<sorted.length;i++){
      for (let j=i+1;j<sorted.length;j++){
        const a=sorted[i], b=sorted[j];
        if (collides(a,b)) {
          // push the lower one below the higher; if b is the moved item, push a? 
          b.y = a.y + a.h;
          any = true;
        }
      }
    }
    if (!any) break;
    res = sorted;
  }
  return res;
}
