export function compact(n: number): string {
  const abs = Math.abs(n);
  if (abs >= 1e9) return trim(n / 1e9) + 'B';
  if (abs >= 1e6) return trim(n / 1e6) + 'M';
  if (abs >= 1e4) return trim(n / 1e3) + 'K';   // 12.9K
  return n.toLocaleString('en-US');              // 1,284
}
function trim(v: number) {
  const s = v >= 100 ? Math.round(v).toString() : v.toFixed(1);
  return s.endsWith('.0') ? s.slice(0, -2) : s;
}
export const full = (n: number) => n.toLocaleString('en-US');
export const money = (n: number) => '$' + compact(n);
export function axisTick(v: number): string {
  // round to clean numbers, in full under 10,000, compact above
  return Math.abs(v) < 10000 ? full(v) : compact(v);
}
