  return s.endsWith('.0') ? s.slice(0, -2) : s;
}
export const full = (n: number) => n.toLocaleString('en-US');
export const money = (n: number) => '$' + compact(n);
export function axisTick(v: number): string {
  // round to clean numbers, in full under 10,000, compact above
  return Math.abs(v) < 10000 ? full(v) : compact(v);
}
