import { useCallback, useEffect, useMemo, useState } from 'react';
import { Button, DropdownMenu, Icon, SegmentedRadioGroup, Switch, ThemeProvider } from '@gravity-ui/uikit';
import { ArrowRotateLeft, Moon, Plus, Sun } from '@gravity-ui/icons';
import { GridLayout, compact, type GridItem } from './grid';
import { WIDGET_META, WidgetContent, type WidgetId } from './widgets';
import { getDashboardData, type RangeKey } from './data';
import './viz.css';

const ALL_IDS = Object.keys(WIDGET_META) as WidgetId[];
const LS_KEY = 'viz-dash-layout-v1';

function defaultItems(): GridItem[] { return ALL_IDS.map((id) => ({ id, ...WIDGET_META[id].def })); }

function load(): { items: GridItem[]; hidden: WidgetId[] } {
  try {
    const raw = localStorage.getItem(LS_KEY);
    if (raw) {
      const p = JSON.parse(raw);
      if (Array.isArray(p.items) && Array.isArray(p.hidden)) {
        // validate ids
        const items = p.items.filter((i: GridItem) => ALL_IDS.includes(i.id as WidgetId));
        const hidden = p.hidden.filter((h: string) => ALL_IDS.includes(h as WidgetId));
        if (items.length) return { items, hidden };
      }
    }
  } catch { /* ignore */ }
  return { items: defaultItems(), hidden: [] };
}

export function App() {
  const [{ items, hidden }, setState] = useState(load);
  const [range, setRange] = useState<RangeKey>('30');
  const [dark, setDark] = useState(() => window.matchMedia?.('(prefers-color-scheme: dark)').matches ?? false);
  const data = useMemo(() => getDashboardData(range), [range]);

  useEffect(() => {
    document.documentElement.dataset.theme = dark ? 'dark' : 'light';
  }, [dark]);

  useEffect(() => {
    try { localStorage.setItem(LS_KEY, JSON.stringify({ items, hidden })); } catch {}
  }, [items, hidden]);

  const onChange = useCallback((next: GridItem[]) => setState((s) => ({ ...s, items: next })), []);
  const removeWidget = useCallback((id: string) => setState((s) => ({ ...s, hidden: [...s.hidden, id as WidgetId], items: s.items.filter((i) => i.id !== id) })), []);
  const addWidget = useCallback((id: WidgetId) => setState((s) => {
    const bottom = s.items.reduce((m, i) => Math.max(m, i.y + i.h), 0);
    const items = compact([...s.items, { id, ...WIDGET_META[id].def, y: bottom }]);
    return { items, hidden: s.hidden.filter((h) => h !== id) };
  }), []);
  const reset = useCallback(() => setState({ items: defaultItems(), hidden: [] }), []);

  const visible = items.filter((i) => !hidden.includes(i.id as WidgetId));

  return (
    <ThemeProvider theme={dark ? 'dark' : 'light'}>
      <div className="dash">
        <header className="dash__header">
          <div>
            <h1 className="dash__title">Product overview</h1>
            <p className="dash__subtitle">Drag widgets by their header, resize from the corner — the layout is yours.</p>
          </div>
          <div className="dash__controls">
            <SegmentedRadioGroup size="m" value={range} onUpdate={(v) => setRange(v as RangeKey)} options={[{value:'7',content:'7 days'},{value:'30',content:'30 days'},{value:'90',content:'90 days'}]} aria-label="Date range" />
            <DropdownMenu
              disabled={hidden.length === 0}
              items={hidden.map((id) => ({ action: () => addWidget(id), text: WIDGET_META[id].title }))}
              renderSwitcher={({ onClick, onKeyDown }) => (
                <Button view="outlined" onClick={onClick} onKeyDown={onKeyDown} disabled={hidden.length === 0}>
                  <Icon data={Plus} size={16} /> Add widget
                </Button>
              )}
            />
            <Button view="flat-secondary" title="Reset layout" aria-label="Reset layout" onClick={reset}>
              <Icon data={ArrowRotateLeft} size={16} />
            </Button>
            <label className="dash__theme">
              {dark ? <Icon data={Moon} size={16}/> : <Icon data={Sun} size={16}/>}
              <Switch checked={dark} onUpdate={setDark} aria-label="Dark theme" />
            </label>
          </div>
        </header>
        <GridLayout
          items={visible}
          meta={metaRecord}
          onChange={onChange}
          renderItem={(id, handle) => (
            <WidgetCard id={id as WidgetId} title={WIDGET_META[id as WidgetId].title} dragHandleProps={handle} onRemove={() => removeWidget(id)}>
              <WidgetContent id={id as WidgetId} data={data} range={range} />
            </WidgetCard>
          )}
        />
      </div>
    </ThemeProvider>
  );
}
