```

Actually simpler: keep live px as clamped pointer-follow: `px: { left, top, width: d.px.width, height: d.px.height }`. The item visually follows the pointer; the placeholder shows the snapped cell (which equals item.x/y in state). On drop, item animates to the snapped cell. Nice.

```
        setDrag({ ...d, px: { ...d.px, left, top } });
      } else {
        const itPx0 = toPx(item); // item.x/y fixed during resize
        let wpx = Math.max(px - itPx0.left, m.minW * pitchX - gap);
        let hpx = Math.max(py - itPx0.top, m.minH * pitchY - gap);
        const maxW = Math.min(m.maxW ?? cols, cols - item.x);
        let gw = Math.min(Math.max(Math.round((wpx + gap) / pitchX), m.minW), maxW);
        let gh = Math.min(Math.max(Math.round((hpx + gap) / pitchY), m.minH), m.maxH ?? 50);
        if (gw !== item.w || gh !== item.h) {
          onChange(resolveLayout(itemsNow, { ...item, w: gw, h: gh }));
        }
        const snapped = toPx({ ...item, w: gw, h: gh });
        setDrag({ ...d, px: snapped });
      }
    };
    const onUp = () => {
      onChange(compact(itemsRef.current));
      setDrag(null);
    };
    window.addEventListener('pointermove', onMove);
    window.addEventListener('pointerup', onUp);
    return () => { window.removeEventListener('pointermove', onMove); window.removeEventListener('pointerup', onUp); };
  }, [drag !== null]);
```

