  const base = [item('a', 0, 0, 6, 2), item('b', 0, 4, 6, 2)];
  const out = resolveLayout(base, item('b', 0, 1, 6, 2));
  expect(out.find((i) => i.id === 'b')?.y).toBe(1);
  expect(out.find((i) => i.id === 'a')?.y).toBe(3);
